PRAGMA foreign_keys = ON;
CREATE TABLE identities (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE staff_profiles (identity_id TEXT PRIMARY KEY REFERENCES identities(id) ON DELETE CASCADE, handle TEXT NOT NULL COLLATE NOCASE UNIQUE, display_name TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', avatar_asset_id TEXT, role TEXT NOT NULL CHECK(role IN ('superadmin','author')), publish_mode TEXT NOT NULL CHECK(publish_mode IN ('direct_publish','review_required')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE staff_handle_aliases (handle TEXT PRIMARY KEY COLLATE NOCASE, identity_id TEXT NOT NULL REFERENCES identities(id) ON DELETE CASCADE, created_at TEXT NOT NULL);
CREATE TABLE reader_profiles (identity_id TEXT PRIMARY KEY REFERENCES identities(id) ON DELETE CASCADE, username TEXT NOT NULL COLLATE NOCASE UNIQUE, avatar_key TEXT NOT NULL, email_visible INTEGER NOT NULL DEFAULT 0, joined_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','banned')));
CREATE TABLE otp_challenges (id TEXT PRIMARY KEY, identity_kind TEXT NOT NULL CHECK(identity_kind IN ('staff','reader')), email TEXT NOT NULL, code_digest BLOB NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, consumed_at TEXT);
CREATE INDEX otp_email_idx ON otp_challenges(identity_kind,email,created_at DESC);
CREATE TABLE rate_limit_buckets (bucket_key TEXT NOT NULL, window_start TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(bucket_key,window_start));
CREATE TABLE sessions (id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identities(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('staff','reader')), token_digest BLOB NOT NULL UNIQUE, csrf_digest BLOB NOT NULL, user_agent TEXT NOT NULL, ip_address TEXT NOT NULL, created_at TEXT NOT NULL, last_activity_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT);
CREATE INDEX sessions_identity_idx ON sessions(identity_id,kind,expires_at);
CREATE TABLE categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '');
CREATE TABLE tags (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE);
CREATE TABLE posts (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES identities(id), title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, excerpt TEXT NOT NULL DEFAULT '', category_id TEXT REFERENCES categories(id), thumbnail_asset_id TEXT, state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','in_review','published','frozen')), published_version_id TEXT, source_post_id TEXT REFERENCES posts(id), source_version_id TEXT, ever_published INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, published_at TEXT);
CREATE TABLE post_drafts (post_id TEXT PRIMARY KEY REFERENCES posts(id) ON DELETE CASCADE, content_json TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE post_versions (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, number INTEGER NOT NULL, content_json TEXT NOT NULL, title TEXT NOT NULL, excerpt TEXT NOT NULL, reason TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES identities(id), created_at TEXT NOT NULL, UNIQUE(post_id,number));
CREATE TABLE review_decisions (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, version_id TEXT NOT NULL REFERENCES post_versions(id) ON DELETE CASCADE, submitted_by TEXT NOT NULL REFERENCES identities(id), decided_by TEXT REFERENCES identities(id), status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','cancelled')), reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, decided_at TEXT);
CREATE UNIQUE INDEX one_pending_review ON review_decisions(post_id) WHERE status='pending';
CREATE TABLE slug_aliases (slug TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, created_at TEXT NOT NULL);
CREATE TABLE post_tags (post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(post_id,tag_id));
CREATE VIRTUAL TABLE post_search USING fts5(post_id UNINDEXED, title, excerpt, body);
CREATE TABLE media_assets (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES identities(id), content_hash TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, bytes INTEGER NOT NULL, alt_text TEXT NOT NULL, caption TEXT NOT NULL DEFAULT '', credit TEXT NOT NULL DEFAULT '', focal_x REAL, focal_y REAL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','public','orphaned')), created_at TEXT NOT NULL, orphaned_at TEXT);
CREATE TABLE article_media (post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES media_assets(id), placement TEXT NOT NULL CHECK(placement IN ('thumbnail','center','wide','full','left','right')), PRIMARY KEY(post_id,asset_id,placement));
CREATE TABLE comments (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, reader_id TEXT REFERENCES identities(id) ON DELETE SET NULL, parent_id TEXT REFERENCES comments(id), depth INTEGER NOT NULL CHECK(depth BETWEEN 0 AND 2), public_version_id TEXT, pending_version_id TEXT, status TEXT NOT NULL CHECK(status IN ('pending','approved','hidden','deleted','rejected')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE comment_versions (id TEXT PRIMARY KEY, comment_id TEXT NOT NULL REFERENCES comments(id) ON DELETE CASCADE, body TEXT NOT NULL, created_by TEXT REFERENCES identities(id) ON DELETE SET NULL, created_at TEXT NOT NULL);
CREATE TABLE comment_reports (id TEXT PRIMARY KEY, comment_id TEXT NOT NULL REFERENCES comments(id) ON DELETE CASCADE, reader_id TEXT NOT NULL REFERENCES identities(id) ON DELETE CASCADE, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL, resolved_at TEXT, resolved_by TEXT REFERENCES identities(id), UNIQUE(comment_id,reader_id));
CREATE TABLE bookmarks (reader_id TEXT NOT NULL REFERENCES identities(id) ON DELETE CASCADE, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(reader_id,post_id));
CREATE TABLE account_suspensions (id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identities(id) ON DELETE CASCADE, starts_at TEXT NOT NULL, ends_at TEXT, reason TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES identities(id), created_at TEXT NOT NULL);
CREATE TABLE audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id TEXT, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, detail_json TEXT NOT NULL DEFAULT '{}', ip_address TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX audit_cursor_idx ON audit_events(created_at DESC,id DESC);
CREATE TABLE idempotency_keys (identity_id TEXT NOT NULL, operation TEXT NOT NULL, key TEXT NOT NULL, response_status INTEGER, response_json TEXT, created_at TEXT NOT NULL, PRIMARY KEY(identity_id,operation,key));
